function manualAttendance(){let type=state.ctx.type||'students',arr=db[type],today=state.ctx.date||localDate();app.innerHTML=shell(`${type==='students'?'Student':'Teacher'} Attendance`,`<div class="panel"><div class="row"><input id="attDate" type="date" value="${today}" style="flex:1" onchange="SV.attDate(this.value)"><button class="btn green" onclick="SV.markAll('Present')">Mark All Present</button><button class="btn danger" onclick="SV.markAll('Absent')">Mark All Absent</button><button class="btn orange" onclick="SV.markAll('Leave')">Mark All Leave</button></div></div><div class="panel" id="attList">${arr.map(x=>{let rec=db.attendance.find(a=>a.type===type&&a.personId===x.id&&String(a.date).slice(0,10)===today);return `<div class="att-row" data-id="${x.id}" data-status="${rec?.status||''}"><b>${esc(x.name)}</b><button class="att p" onclick="SV.pickAtt(this,'Present')">Present</button><button class="att a" onclick="SV.pickAtt(this,'Absent')">Absent</button><button class="att l" onclick="SV.pickAtt(this,'Leave')">Leave</button></div>`}).join('')}</div><button class="btn primary" style="width:100%" onclick="SV.saveManual('${type}')">Save Attendance</button>`);setTimeout(()=>document.querySelectorAll('.att-row').forEach(r=>{let st=r.dataset.status;if(st){let b=r.querySelector(st==='Present'?'.p':st==='Absent'?'.a':'.l');if(b)b.style.outline='2px solid #333'}}),0)}

