async function upsertAtt(personId,type,date,status,source='Manual',eventType='manual'){
 let key=`${type}|${personId}|${date}`,o={key,attendanceKey:key,personId,personType:type,type,date,status,source,eventType,modifiedAt:new Date().toISOString()};
 if(source==='Face'){o.time=fmtTime(new Date());o.lastMarkedTime=o.time}else{o.arrivalTime='';o.departureTime='';o.lastMarkedTime='';o.time=''}
 let i=db.attendance.findIndex(a=>(a.key||a.attendanceKey)===key);i<0?db.attendance.push(o):db.attendance[i]={...db.attendance[i],...o};save();
 let r=await apiWrite('upsertAttendance',{record:o},{timeout:18000});
 if(r.ok&&r.data){let x=r.data,norm={...x,key:x.attendanceKey||key,type:normalizeFaceType(x.personType||type),time:x.lastMarkedTime||''};i=db.attendance.findIndex(a=>(a.key||a.attendanceKey)===key);i<0?db.attendance.push(norm):db.attendance[i]=norm;save();return norm}
 return o
}
async function saveManual(type){
 let date=$('#attDate').value,rows=[...document.querySelectorAll('.att-row')].filter(r=>r.dataset.status);
 if(!rows.length)return showPopup('Select attendance status first.','warning');
 let records=rows.map(r=>({attendanceKey:`${type}|${r.dataset.id}|${date}`,personType:type,personId:r.dataset.id,date,status:r.dataset.status,source:'Manual',eventType:'manual',arrivalTime:'',departureTime:'',lastMarkedTime:'',modifiedAt:new Date().toISOString()}));
 records.forEach(o=>{let key=o.attendanceKey,i=db.attendance.findIndex(a=>(a.key||a.attendanceKey)===key),loc={...o,key,type};i<0?db.attendance.push(loc):db.attendance[i]={...db.attendance[i],...loc}});save();
 let btn=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Save Attendance');if(btn){btn.disabled=true;btn.textContent='Saving…'}
 let r=await apiWrite('bulkUpsertAttendance',{records},{timeout:25000});
 if(btn){btn.disabled=false;btn.textContent='Save Attendance'}
 if(!r.ok)return showPopup(r.message||'Attendance could not be saved to spreadsheet.','error',4200);
 if(Array.isArray(r.data))r.data.forEach(x=>{let key=x.attendanceKey,i=db.attendance.findIndex(a=>(a.key||a.attendanceKey)===key),norm={...x,key,type:normalizeFaceType(x.personType)};i<0?db.attendance.push(norm):db.attendance[i]=norm});save();
 showPopup(`${rows.length} attendance records saved to spreadsheet`,'success');setTimeout(()=>syncData(true,true),250)
}

function monthKey(){let d=new Date(),ym=state.ctx.ym||`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;return ym}
function monthlyRegister(){let type=state.ctx.type||'students',ym=monthKey(),[y,m]=ym.split('-').map(Number),first=new Date(y,m-1,1).getDay(),days=new Date(y,m,0).getDate(),arr=db[type],person=state.ctx.person||arr[0]?.id||'';let cells=Array(first).fill('<div class="day empty"></div>');for(let d=1;d<=days;d++){let date=`${ym}-${String(d).padStart(2,'0')}`,rec=db.attendance.find(a=>a.type===type&&a.personId===person&&String(a.date).slice(0,10)===date),sun=new Date(y,m-1,d).getDay()===0;cells.push(`<button type="button" class="day ${sun?'leave':''} ${rec?('has-att '+String(rec.status||'').toLowerCase().replace(/\s+/g,'-')):''}" onclick="SV.editAttendanceDay('${type}','${person}','${date}')"><b>${d}</b>${rec?`<small style="display:block;margin-top:5px">${esc(rec.status)}</small>`:sun?'<small style="display:block">Sunday</small>':''}</button>`)}app.innerHTML=shell(`${type==='students'?'Student':'Teacher'} Monthly Register`,`<div class="panel"><div class="row"><button class="btn" onclick="SV.shiftMonth(-1)">‹ Previous</button><input type="month" value="${ym}" onchange="SV.setMonth(this.value)"><button class="btn" onclick="SV.shiftMonth(1)">Next ›</button><select onchange="SV.setPerson(this.value)">${arr.map(p=>`<option value="${p.id}" ${p.id===person?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div><div class="panel"><div class="calendar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="dayhead">${x}</div>`).join('')}${cells.join('')}</div><small>Tap any date to update that day's attendance.</small></div>`)}

function setMonth(v){state.ctx.ym=v;persist();monthlyRegister()}function setPerson(v){state.ctx.person=v;persist();monthlyRegister()}
function shiftMonth(delta){let [y,m]=monthKey().split('-').map(Number),d=new Date(y,m-1+delta,1);state.ctx.ym=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;persist();monthlyRegister()}
function editAttendanceDay(type,personId,date){let rec=db.attendance.find(a=>a.type===type&&a.personId===personId&&String(a.date).slice(0,10)===date),p=db[type].find(x=>x.id===personId);document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="attEditModal"><div class="sheet"><h3>${esc(p?.name||personId)} • ${date}</h3><label class="f">Status<select id="dayStatus">${['Present','Absent','Leave','Half Day'].map(v=>`<option ${rec?.status===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="row" style="margin-top:12px"><button class="btn green" onclick="SV.saveAttendanceDay('${type}','${personId}','${date}')">Save</button><button class="btn" onclick="SV.closeModal('attEditModal')">Cancel</button></div></div></div>`)}
async function saveAttendanceDay(type,id,date){await upsertAtt(id,type,date,$('#dayStatus').value,'Manual','manual');closeModal('attEditModal');monthlyRegister();showPopup('Attendance updated.','success')}
async function deleteAttendanceDay(type,id,date){if(!await confirmPopup('Delete this attendance record?'))return;db.attendance=db.attendance.filter(a=>!(a.type===type&&a.personId===id&&String(a.date).slice(0,10)===date));save();closeModal('attEditModal');monthlyRegister();showPopup('Attendance deleted. Syncing…','success');let r=await apiWrite('deleteAttendance',{personType:type,personId:id,date});if(!r.ok)showPopup(r.message||'Delete could not be synced.','error')}
function attendanceSummary(){let month=monthKey(),types=['students','teachers'];let html=types.map(type=>`<div class="panel"><h3>${type==='students'?'Students':'Teachers'}</h3>${db[type].map(p=>{let a=db.attendance.filter(x=>x.type===type&&x.personId===p.id&&x.date.startsWith(month)),P=a.filter(x=>x.status==='Present').length,A=a.filter(x=>x.status==='Absent').length,L=a.filter(x=>x.status==='Leave').length,W=P+A+L,pc=W?Math.round(P/W*100):0;return `<div class="listitem"><div class="grow"><b>${esc(p.name)}</b><small style="display:block">Working Days ${W} • ${pc}%</small></div><span class="pill present">P ${P}</span><span class="pill absent">A ${A}</span><span class="pill leave">L ${L}</span></div>`}).join('')||'No records'}</div>`).join('');app.innerHTML=shell('Attendance Summary',`<div class="panel"><input type="month" value="${month}" onchange="state.ctx.ym=this.value;SV.go('attendanceSummary',{ym:this.value})"></div>${html}`)}
function attendanceReports(){let month=monthKey(),rows=db.attendance.filter(a=>a.date.startsWith(month)).sort((a,b)=>b.date.localeCompare(a.date));app.innerHTML=shell('Attendance Reports',`<div class="panel"><div class="row"><input type="month" value="${month}" onchange="SV.go('attendanceReports',{ym:this.value})"><button class="btn primary" onclick="window.print()">Print Report</button></div></div><div class="panel">${rows.map(a=>{let p=db[a.type]?.find(x=>x.id===a.personId);return `<div class="listitem"><div class="grow"><b>${esc(p?.name||a.personId)}</b><small style="display:block">${fmtDate(a.date)} • ${a.time||''} • ${a.source}</small></div><span class="pill ${a.status.toLowerCase()}">${a.status}</span></div>`}).join('')||'No attendance records for this month.'}</div>`)}
function facePeople(){let type=$('#faceType')?.value||'students',s=$('#facePerson');if(s){s.innerHTML=db[type].map(x=>`<option value="${x.id}">${esc(x.name)} • ${esc(x.id)}</option>`).join('');s.onchange=checkExistingFace;checkExistingFace()}}
function checkExistingFace(){let type=$('#faceType')?.value||'students',id=$('#facePerson')?.value,rec=id&&db.faces.find(f=>normalizeFaceType(f.type||f.personType)===type&&String(f.personId)===String(id)),host=$('#faceRegState');if(host)host.innerHTML=rec?`<div class="accountbox">${Array.isArray(rec.signature)&&rec.signature.length===100?'✓ Face is registered.':'⚠ Previous face data needs updating.'} Capture 5 new photos and Save Registration to update it. <button class="btn danger" style="margin-left:8px" onclick="SV.deleteFaceRegistration('${type}','${id}')">Delete Registration</button></div>`:''}
async function startCam(mode=facing){stopCam();facing=mode;let v=$('#cam');try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera API unavailable');let tries=[{video:{facingMode:{ideal:mode},width:{ideal:640},height:{ideal:480}},audio:false},{video:true,audio:false}];let err;for(const c of tries){try{stream=await navigator.mediaDevices.getUserMedia(c);break}catch(e){err=e}}if(!stream)throw err||Error('Camera unavailable');if(v){v.srcObject=stream;v.muted=true;v.setAttribute('playsinline','');await v.play().catch(()=>{});}return true}catch(e){showPopup(localStorage.getItem('sv_lang')==='hi'?'कैमरा नहीं खुल सका। कैमरा अनुमति जाँचें।':'Camera could not open. Check camera permission.','error',4200);return false}}function stopCam(){stopAutoScan();stream?.getTracks().forEach(t=>t.stop());stream=null}
function faceRegistration(){app.innerHTML=shell('Face Registration',`<div class="panel"><div class="row"><select id="faceType" onchange="SV.facePeople()"><option value="students">Student</option><option value="teachers">Teacher</option></select><select id="facePerson"></select></div><div id="faceRegState" style="margin-top:8px"></div></div><div class="panel"><div class="capture"><div class="camera"><video id="cam" autoplay playsinline muted></video></div><div class="previews" id="prev">${Array(5).fill('<div class="preview-empty"></div>').join('')}</div></div><div class="row" style="margin-top:9px"><button class="btn" style="flex:1" onclick="SV.switchCam()">Switch Camera</button><button class="btn" style="flex:1" onclick="SV.resetFace()">Reset</button></div><div class="row" style="margin-top:7px"><button class="btn green" style="flex:1" onclick="SV.captureFace()">Capture Image</button><button class="btn primary" style="flex:1" onclick="SV.saveFace()">Save Registration</button></div><small>Capture exactly 5 clear images manually.</small></div>`);facePeople();captures=[];startCam()}
async function captureFace(){if(captures.length>=5)return toast('Five images already captured');let v=$('#cam');if(!v?.videoWidth)return toast('Camera not ready');let c=document.createElement('canvas'),ratio=v.videoWidth/Math.max(1,v.videoHeight),h=300,w=Math.round(h*ratio);c.width=Math.max(220,w);c.height=h;c.getContext('2d').drawImage(v,0,0,c.width,c.height);let item={src:c.toDataURL('image/jpeg',.72),sig:null,pending:true,promise:null};item.promise=imageSignature(item.src).then(sig=>{item.sig=sig;item.pending=false;renderFacePreviews();return sig}).catch(()=>{item.pending=false;item.sig=null;renderFacePreviews();return null});captures.push(item);renderFacePreviews()}
function renderFacePreviews(){let p=$('#prev');if(!p)return;p.innerHTML=captures.map(x=>`<div class="preview-wrap"><img src="${x.src}"><small>${x.pending?'…':x.sig?'✓':'!'}</small></div>`).join('')+Array(5-captures.length).fill('<div class="preview-empty"></div>').join('')}
function resetFace(){captures=[];renderFacePreviews()}
let faceModelsReady=false;
async function ensureFaceModels(){if(faceModelsReady)return true;if(!window.faceapi){showPopup('Face recognition library could not be loaded.','error');return false}try{await Promise.all([faceapi.nets.tinyFaceDetector.loadFromUri('assets/face-api/models'),faceapi.nets.faceLandmark68TinyNet.loadFromUri('assets/face-api/models')]);faceModelsReady=true;return true}catch(e){showPopup('Face recognition models could not be loaded.','error');return false}}
function landmarkSignature(det){
 const pts=det.landmarks.positions;if(!pts||pts.length<68)return null;
 const pick=[0,4,8,12,16,17,19,21,22,24,26,27,30,31,33,35,36,39,42,45,48,51,54,57];
 const le=avgPoint(pts.slice(36,42)),re=avgPoint(pts.slice(42,48)),scale=Math.max(1,Math.hypot(re.x-le.x,re.y-le.y));
 let out=[];for(let i=0;i<pick.length;i++)for(let j=i+1;j<pick.length;j+=3){let a=pts[pick[i]],b=pts[pick[j]];out.push(Math.hypot(a.x-b.x,a.y-b.y)/scale)}
 return out
}
function avgPoint(a){let x=0,y=0;a.forEach(p=>{x+=p.x;y+=p.y});return{x:x/a.length,y:y/a.length}}

async function imageSignature(src){if(!await ensureFaceModels())return null;let im=new Image();im.src=src;await new Promise((res,rej)=>{im.onload=res;im.onerror=rej});let d=await faceapi.detectSingleFace(im,new faceapi.TinyFaceDetectorOptions({inputSize:160,scoreThreshold:.25})).withFaceLandmarks(true);return d?landmarkSignature(d):null}
function dist(a,b){if(!a||!b||a.length!==b.length)return 99;return Math.sqrt(a.reduce((s,v,i)=>s+(v-b[i])**2,0)/a.length)}
async function saveFace(){
 if(captures.length!==5)return showPopup('Capture all 5 images first.','warning');
 let saveBtn=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Save Registration');if(saveBtn){saveBtn.disabled=true;saveBtn.textContent='Processing…'}
 await Promise.all(captures.map(x=>x.promise||Promise.resolve(x.sig)));
 if(captures.some(x=>!x.sig)){if(saveBtn){saveBtn.disabled=false;saveBtn.textContent='Save Registration'}return showPopup('Face could not be detected in one or more photos. Keep the face centred and capture again.','warning',4200)}
 let type=$('#faceType').value,id=$('#facePerson').value,person=db[type].find(x=>x.id===id),sigs=captures.map(x=>x.sig),avg=sigs[0].map((_,i)=>sigs.reduce((sum,a)=>sum+(Number(a[i])||0),0)/sigs.length);
 let others=db.faces.filter(f=>!(normalizeFaceType(f.type||f.personType)===type&&String(f.personId)===String(id))&&Array.isArray(f.signature)&&f.signature.length===avg.length),same=others.map(f=>({f,d:dist(f.signature,avg)})).sort((a,b)=>a.d-b.d)[0];
 if(same&&same.d<.035){if(saveBtn){saveBtn.disabled=false;saveBtn.textContent='Save Registration'}let other=db[normalizeFaceType(same.f.type||same.f.personType)]?.find(x=>String(x.id)===String(same.f.personId));return showPopup(`This face appears to be registered${other?.name?' for '+other.name:''}. Please check the selected person.`, 'warning',4500)}
 let rec={personId:id,type,personType:type,signature:avg,registeredAt:new Date().toISOString()};let fi=db.faces.findIndex(f=>normalizeFaceType(f.type||f.personType)===type&&String(f.personId)===String(id));fi<0?db.faces.push(rec):db.faces[fi]=rec;save();
 if(saveBtn)saveBtn.textContent='Saving…';let r=await apiWrite('registerFace',{personType:type,personId:id,signature:avg,replace:true},{timeout:18000});if(saveBtn){saveBtn.disabled=false;saveBtn.textContent='Save Registration'}
 if(!r.ok)return showPopup(r.message||'Unable to save face registration.','error',4200);showPopup(`Face registered for ${person?.name||'selected person'}.`,'success');resetFace();checkExistingFace();setTimeout(()=>syncData(true,true),250)
}
function switchCam(){startCam(facing==='user'?'environment':'user')}
function faceAttendance(){let hi=localStorage.getItem('sv_lang')==='hi',validFaces=db.faces.filter(f=>Array.isArray(f.signature)&&f.signature.length===100);if(db.faces.length&&!validFaces.length)showPopup('Existing face registrations use the old format. Re-register faces once for faster and safer identification.','warning',5200);app.innerHTML=shell(hi?'फेस उपस्थिति':'Face Attendance',`<div class="panel face-att-panel"><div class="camera face-att-camera"><video id="cam" autoplay playsinline muted></video><div class="scan-line"></div></div><div id="faceStatus" class="face-status">${hi?'चेहरा स्कैन करने के लिए तैयार':'Ready to scan face'}</div><div class="row"><button class="btn" style="width:100%" onclick="SV.switchCam()">${hi?'कैमरा बदलें':'Switch Camera'}</button></div></div>`);startCam().then(ok=>{if(ok)startAutoScan()})}
let autoScanTimer=null,scanBusy=false,lastFaceMark={};
function stopAutoScan(){if(autoScanTimer){clearInterval(autoScanTimer);autoScanTimer=null}scanBusy=false}
async function startAutoScan(){stopAutoScan();if(!await ensureFaceModels())return;autoScanTimer=setInterval(()=>scanFace(true),240);scanFace(true)}
function localDate(){let d=new Date(),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
async function scanFace(auto=false){if(scanBusy)return;scanBusy=true;try{
 if(!db.faces.length){if(!auto)showPopup('No registered faces found.','warning');return}
 let v=$('#cam');if(!v?.videoWidth)return;
 let det=await faceapi.detectSingleFace(v,new faceapi.TinyFaceDetectorOptions({inputSize:128,scoreThreshold:.25})).withFaceLandmarks(true);if(!det){if($('#faceStatus'))$('#faceStatus').textContent='Scanning face…';return}
 let sig=landmarkSignature(det);if(!sig)return;let matches=[];for(let f of db.faces){if(!Array.isArray(f.signature)||f.signature.length!==sig.length)continue;matches.push({f,d:dist(f.signature,sig)})}matches.sort((a,b)=>a.d-b.d);let best=matches[0],second=matches[1];
 if(!best||best.d>.052||(second&&second.d-best.d<.006)){if($('#faceStatus'))$('#faceStatus').textContent='Face detected — move closer and look straight';return}
 let faceType=normalizeFaceType(best.f.type||best.f.personType),p=db[faceType]?.find(x=>String(x.id)===String(best.f.personId));if(!p)return;
 let coolKey=faceType+'|'+p.id,now=Date.now();if($('#faceStatus'))$('#faceStatus').innerHTML=`<b>${esc(p.name)}</b> • Recognized`;if(lastFaceMark[coolKey]&&now-lastFaceMark[coolKey]<5000)return;lastFaceMark[coolKey]=now;
 let r=await apiWrite('markFaceAttendance',{personType:faceType,personId:String(p.id)},{timeout:15000});if(r.ok&&r.data){let rec=r.data.attendance;if(rec){let k=rec.attendanceKey||`${faceType}|${p.id}|${localDate()}`,i=db.attendance.findIndex(a=>(a.key||a.attendanceKey)===k),norm={...rec,key:k,type:normalizeFaceType(rec.personType||faceType),time:rec.lastMarkedTime||''};i<0?db.attendance.push(norm):db.attendance[i]=norm;save()}showPopup(r.data.message||`${p.name}: attendance saved`,r.data.duplicate?'warning':'success',2600);setTimeout(()=>syncData(true,true),180)}else if(!r.ok)showPopup(r.message||`${p.name}: attendance could not be saved`,'error',3200)
 }catch(e){if(!auto)showPopup('Face scan could not be completed. Please try again.','error')}finally{scanBusy=false}}
function notifications(){let rows=(db.notifications||[]).slice().reverse();app.innerHTML=shell('Notifications',`<div class="panel tint"><div class="row"><div class="grow"><b>Notifications</b><small style="display:block">${rows.length} notification${rows.length===1?'':'s'}</small></div><button class="btn danger" ${rows.length?'':'disabled'} onclick="SV.clearNotifications()">Clear All</button></div></div><div class="panel">${rows.map(n=>`<div class="listitem"><div class="grow"><b>${esc((n.notificationType||'Notification').replace(/^./,c=>c.toUpperCase()))}</b><small style="display:block">${esc(n.message||'')}</small><small style="display:block;margin-top:4px">${esc(fmtDateTime(n.createdAt||n.at))}</small></div></div>`).join('')||'<div>No notifications yet.</div>'}</div>`)}
