function noticeList(group){let arr=group==='all'?[...db.teachers,...db.students]:db[group],sub=$('#noticeSubject').value,text=$('#noticeText').value;if(!text)return toast('Enter notice message');document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="noticeModal"><div class="sheet"><h3>Select Recipients</h3><label class="notice-person"><b>Select All</b><input type="checkbox" onchange="document.querySelectorAll('.nr').forEach(x=>x.checked=this.checked)"></label>${arr.map(x=>`<label class="notice-person"><span>${esc(x.name)}</span><input class="nr" type="checkbox" value="${x.id}" data-mobile="${x.mobile||x.guardianMobile||x.fatherMobile||''}"></label>`).join('')}<button class="btn green" style="width:100%;margin-top:10px" onclick="SV.sendNotice('${group}','${esc(sub)}','${esc(text).replace(/'/g,'&#39;')}')">Send Selected</button><button class="btn" style="width:100%;margin-top:7px" onclick="SV.closeModal('noticeModal')">Cancel</button></div></div>`)}
