function wa(num,msg){num=String(num||'').replace(/\D/g,'');if(num.length===10)num='91'+num;location.href=`https://wa.me/${num}?text=${encodeURIComponent(msg)}`}
async function canvasPhotoSrc(p){if(p?.photo&&String(p.photo).startsWith('data:'))return p.photo;if(p?.photoFileId&&navigator.onLine){let r=await api('getMediaData',{fileId:p.photoFileId},15000);if(r.ok&&r.data?.dataUrl)return r.data.dataUrl}return photoOf(p)}
async function idCard(id){let s=db.students.find(a=>a.id===id);if(!s)return;let cv=document.createElement('canvas');cv.width=1011;cv.height=639;let x=cv.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,1011,639);x.fillStyle='#2f6d00';x.beginPath();x.moveTo(0,0);x.lineTo(282,0);x.lineTo(0,164);x.fill();x.fillStyle='#ffd31c';x.beginPath();x.moveTo(0,120);x.lineTo(110,120);x.lineTo(0,260);x.fill();x.fillStyle='#2f6d00';x.beginPath();x.moveTo(1011,430);x.lineTo(1011,639);x.lineTo(560,639);x.fill();x.fillStyle='#ffd31c';x.beginPath();x.moveTo(910,324);x.lineTo(1011,380);x.lineTo(1011,500);x.lineTo(728,500);x.fill();x.fillStyle='#ff7317';x.beginPath();x.moveTo(962,365);x.lineTo(1011,392);x.lineTo(1011,469);x.lineTo(915,416);x.fill();x.fillStyle='#426c12';x.font='700 25px Arial';x.fillText('Sewangan Vidyapeeth',520,70);x.fillStyle='#666';x.font='15px Arial';x.fillText('Run under the aegis of Sewangan Charitable Trust',520,100);let load=src=>new Promise((res,rej)=>{let i=new Image();if(/^https?:/i.test(src))i.crossOrigin='anonymous';i.onload=()=>res(i);i.onerror=rej;i.src=src});try{x.drawImage(await load('assets/images/logo.png'),900,18,82,82)}catch(e){}x.fillStyle='#e9f3f8';x.fillRect(66,152,250,335);try{let im=await load(await canvasPhotoSrc(s)),sc=Math.max(250/im.width,335/im.height),w=im.width*sc,h=im.height*sc;x.save();x.beginPath();x.rect(66,152,250,335);x.clip();x.drawImage(im,66+(250-w)/2,152+(335-h)/2,w,h);x.restore()}catch(e){}x.fillStyle='#09253d';x.font='700 52px Arial';x.fillText(s.name||'Student',385,255);x.fillStyle='#2f6d00';x.fillRect(382,300,365,45);x.fillStyle='#fff';x.font='700 22px Arial';x.fillText('Student ID : '+s.id,395,331);x.fillStyle='#333';x.font='22px Arial';x.fillText(`Class : ${s.className||'5'}   Roll No. : ${s.rollNo||''}`,388,395);x.fillText(`+91 ${s.fatherMobile||s.guardianMobile||s.mobile||''}`,388,438);x.font='20px Arial';x.fillText((s.address||'').slice(0,48),388,480);let data=cv.toDataURL('image/jpeg',.94);window.__id={data,name:(s.name||'student').replace(/\s+/g,'_')};document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="idModal"><div class="sheet"><h3>Student ID Card</h3><div class="idwrap"><img class="idcard-canvas" src="${data}"></div><div class="row" style="justify-content:center;margin-top:12px"><button class="btn primary" onclick="SV.idView()">View</button><button class="btn orange" onclick="SV.idDownload()">Download</button><button class="btn green" onclick="SV.idShare()">Share</button><button class="btn" onclick="SV.closeModal('idModal')">Close</button></div></div></div>`)}
