const backendFieldMap={requests:{'Person Type':'personType','Person':'personName','Request Type':'requestType','From Date':'fromDate','To Date':'toDate','Reason':'reason','Status':'status','Admin Remarks':'adminRemarks'},homework:{'Class':'className','Subject':'subject','Teacher':'teacherName','Homework Date':'homeworkDate','Due Date':'dueDate','Homework':'homework','Attachment URL':'attachmentUrl','Status':'status'},timetable:{'Date':'date','Class':'className','Subject':'subject','Teacher':'teacherName','Start Time':'startTime','End Time':'endTime'},welfare:{'Date':'date','Student':'studentName','Item':'item','Quantity':'quantity','Remarks':'remarks'},inventory:{'Item':'item','Category':'category','Quantity':'quantity','Unit':'unit','Status':'status','Remarks':'remarks'},exams:{'Exam Name':'examName','Class':'className','Subject':'subject','Exam Date':'examDate','Maximum Marks':'maximumMarks','Remarks':'remarks'},certificates:{'Student':'studentName','Certificate Type':'certificateType','Issue Date':'issueDate','Certificate No.':'certificateNo','Remarks':'remarks'},svcet:{'Student Name':'studentName','Class':'className','School':'school','Exam Date':'examDate','Marks':'marks','Rank':'rank','Selection Status':'selectionStatus'},ptm:{'Date':'date','Student':'studentName','Guardian':'guardianName','Teacher':'teacherName','Discussion':'discussion','Remarks':'remarks'},holidays:{'Date':'date','Holiday Name':'holidayName','Remarks':'remarks'},schoolProfile:{'Centre Name':'centreName','Centre Code':'centreCode','Session':'session','Mobile':'mobile','Email':'email','Address':'address'},adminProfile:{'Name':'name','Mobile':'mobile','Email':'email','Username':'username'}};
