const genericFields={requests:['Person Type','Person','Request Type','From Date','To Date','Reason','Status','Admin Remarks'],homework:['Class','Subject','Teacher','Homework Date','Due Date','Homework','Attachment URL','Status'],timetable:['Date','Class','Subject','Teacher','Start Time','End Time'],welfare:['Date','Student','Item','Quantity','Remarks'],inventory:['Item','Category','Quantity','Unit','Status','Remarks'],exams:['Exam Name','Class','Subject','Exam Date','Maximum Marks','Remarks'],certificates:['Student','Certificate Type','Issue Date','Certificate No.','Remarks'],svcet:['Student Name','Class','School','Exam Date','Marks','Rank','Selection Status'],ptm:['Date','Student','Guardian','Teacher','Discussion','Remarks'],holidays:['Date','Holiday Name','Remarks'],schoolProfile:['Centre Name','Centre Code','Session','Mobile','Email','Address'],adminProfile:['Name','Mobile','Email','Username']};
