function welfareForm(idx){let r=(db.generic.welfare||[])[idx]||{},items=(db.generic.inventory||[]).map(x=>x.item||x.Item).filter(Boolean);document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="genModal"><div class="sheet"><h3>${idx==null?'Add':'Edit'} Welfare</h3><form id="wf"><label class="f">Date<input type="date" name="Date" value="${esc(r.date||r.Date||localDate())}"></label><label class="f">Item<select name="Item">${items.map(x=>`<option ${String(r.item||r.Item)===x?'selected':''}>${esc(x)}</option>`).join('')}<option value="Other">Other</option></select></label><label class="f">Quantity<input name="Quantity" type="number" min="1" value="${esc(r.quantity||r.Quantity||1)}"></label><label class="f">Students<div class="multi-students">${db.students.map(x=>`<label><input type="checkbox" name="studentIds" value="${esc(x.id)}" ${idx!=null&&String(r.studentId||'')===String(x.id)?'checked':''}> ${esc(x.name)}</label>`).join('')}</div></label><label class="f">Remarks<textarea name="Remarks">${esc(r.remarks||r.Remarks||'')}</textarea></label><div class="row" style="margin-top:10px"><button class="btn green">Save</button><button type="button" class="btn" onclick="SV.closeModal('genModal')">Cancel</button></div></form></div></div>`);$('#wf').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),ids=fd.getAll('studentIds');if(!ids.length)return showPopup('Select at least one student.','warning');let common={Date:fd.get('Date'),Item:fd.get('Item'),Quantity:fd.get('Quantity'),Remarks:fd.get('Remarks')};if(idx!=null&&ids.length===1){let st=db.students.find(x=>x.id===ids[0]),rec={...common,Student:st?.name||'',studentId:st?.id||''},res=await apiWrite('upsertModuleRecord',{module:'welfare',index:idx,record:rec});if(res.ok){(db.generic.welfare||[])[idx]=res.data||rec;save();closeModal('genModal');generic('welfare');showPopup('Welfare record saved.','success')}}else{let records=ids.map(id=>{let st=db.students.find(x=>x.id===id);return {...common,Student:st?.name||'',studentId:id}}),res=await apiWrite('bulkUpsertModuleRecords',{module:'welfare',records},{timeout:20000});if(res.ok){db.generic.welfare=[...(db.generic.welfare||[]),...(res.data||records)];save();closeModal('genModal');generic('welfare');showPopup(`${records.length} welfare records saved.`,'success')}else showPopup(res.message||'Unable to save welfare records.','error')}}}
function genericForm(route,idx){if(route==='welfare')return welfareForm(idx);let fields=genericFields[route]||['Title','Date','Description'],r=(db.generic[route]||[])[idx]||{};document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="genModal"><div class="sheet"><h3>${idx==null?'Add':'Edit'} ${route.replace(/([A-Z])/g,' $1')}</h3><form id="gf">${fields.map(f=>`<label class="f">${f}${fieldControl(route,f,genericValue(route,r,f))}</label>`).join('')}<div class="row" style="margin-top:10px"><button class="btn green">Save</button><button type="button" class="btn" onclick="SV.closeModal('genModal')">Cancel</button></div></form></div></div>`);$('#gf').onsubmit=async e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target)),arr=db.generic[route]||(db.generic[route]=[]),localIndex=idx==null?arr.length:idx;if(idx==null)arr.push(o);else arr[idx]={...arr[idx],...o};save();closeModal('genModal');generic(route);toast('Saved. Syncing to spreadsheet…','success');let res=await apiWrite('upsertModuleRecord',{module:route,index:idx,record:o});if(res.ok&&res.data&&typeof res.data==='object'){arr[localIndex]={...arr[localIndex],...res.data};save()}else if(!res.ok)showPopup(res.message||'Unable to sync.','error')}}

async function deleteGeneric(route,idx){if(!await confirmPopup('Delete this record?'))return;(db.generic[route]||[]).splice(idx,1);save();generic(route);showPopup('Record deleted. Syncing…','success');let r=await apiWrite('deleteModuleRecord',{module:route,index:idx});if(!r.ok)showPopup(r.message||'Delete could not be synced.','error')}
function settingsPage(){let st=settingsObject();app.innerHTML=shell('Settings',`<div class="panel"><form id="settingsForm"><div class="fieldgrid"><label class="f">Class Start Time<input type="time" name="classStartTime" value="${esc(st.classStartTime||'17:00')}"></label><label class="f">Arrival Grace (minutes)<input type="number" min="0" max="60" name="arrivalGraceMinutes" value="${esc(st.arrivalGraceMinutes||'10')}"></label><label class="f">Minimum Arrival–Departure Gap (minutes)<input type="number" min="1" max="600" name="minimumDepartureGapMinutes" value="${esc(st.minimumDepartureGapMinutes||'45')}"></label><label class="f">Class End Time<input type="time" name="classEndTime" value="${esc(st.classEndTime||'18:00')}"></label><label class="f">Default Language<select name="defaultLanguage"><option value="en" ${st.defaultLanguage!=='hi'?'selected':''}>English</option><option value="hi" ${st.defaultLanguage==='hi'?'selected':''}>हिन्दी</option></select></label><label class="f">Academic Session<input name="academicSession" value="${esc(st.academicSession||'2026-27')}"></label></div><button class="btn green" style="margin-top:12px">Save Settings</button></form></div>`);$('#settingsForm').onsubmit=async e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target));db.generic.settings=Object.entries(o).map(([settingKey,settingValue])=>({settingKey,settingValue}));save();showPopup('Settings saved. Syncing…','success');let r=await apiWrite('saveSettings',{settings:o});if(!r.ok)showPopup(r.message||'Unable to sync settings.','error')}}
function more(){let c=[['faceRegistration','📸','Face Registration'],['svcet','🎓','SVCET'],['ptm','👥','PTM'],['holidays','🏖️','Holidays'],['schoolProfile','🏫','School Profile'],['adminProfile','👤','Admin Profile'],['settings','⚙️','Settings']];app.innerHTML=shell('More',`<div class="grid module-cards">${c.map(x=>card(...x)).join('')}<button class="cardbtn" onclick="SV.logout()"><span class="ico">⏻</span><span>Log Out</span></button></div>`)}
function closeModal(id){document.getElementById(id)?.remove()}
function render(){stopCam();let r=state.route;if(r==='login')return login();if(r==='home')return home();if(r==='students'||r==='teachers')return people(r);if(r==='profile')return profile();if(r==='attendance')return attendance();if(r==='manualAttendance')return manualAttendance();if(r==='monthlyRegister')return monthlyRegister();if(r==='attendanceSummary')return attendanceSummary();if(r==='attendanceReports')return attendanceReports();if(r==='faceRegistration')return faceRegistration();if(r==='faceAttendance')return faceAttendance();if(r==='notices')return notices();if(r==='notifications')return notifications();if(r==='more')return more();return generic(r)}
async function deleteUserAccount(personId){let i=db.accounts.findIndex(a=>a.personId===personId);if(i<0)return closeModal('acctModal');if(!await confirmPopup('Delete this user account?'))return;let a=db.accounts.splice(i,1)[0];save();await apiWrite('deleteUserAccount',{personId,username:a.username});closeModal('acctModal');toast('User account deleted')}
function setLang(v){localStorage.setItem('sv_lang',v);document.documentElement.lang=v==='hi'?'hi':'en';render();setTimeout(()=>toast(v==='hi'?'भाषा हिन्दी चुनी गई':'Language set to English','success'),40)}
